INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenbanken > ACID-Prinzipien
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Stellt Atomicity sicher, dass eine Transaktion entweder vollständig ausgeführt wird oder gar nicht?', 2, '[{"text": "Ja", "correct": true, "because": "Atomicity garantiert Alles-oder-Nichts"}, {"text": "Nein", "correct": false, "because": "Definition von Atomicity"}]'),
('00000000-0000-0000-0000-000000000000', 'Gewährleistet Consistency, dass die Datenbank nach einer Transaktion in einem konsistenten Zustand bleibt?', 2, '[{"text": "Ja", "correct": true, "because": "Consistency hält Datenbankregeln ein"}, {"text": "Nein", "correct": false, "because": "Kernprinzip von Consistency"}]'),
('00000000-0000-0000-0000-000000000000', 'Verhindert Isolation, dass parallele Transaktionen sich gegenseitig beeinflussen?', 2, '[{"text": "Ja", "correct": true, "because": "Isolation trennt Transaktionen"}, {"text": "Nein", "correct": false, "because": "Zweck von Isolation"}]'),
('00000000-0000-0000-0000-000000000000', 'Sichert Durability, dass einmal committete Transaktionen auch nach einem Systemausfall erhalten bleiben?', 2, '[{"text": "Ja", "correct": true, "because": "Durability garantiert Dauerhaftigkeit"}, {"text": "Nein", "correct": false, "because": "Definition von Durability"}]'),
('00000000-0000-0000-0000-000000000000', 'Können die ACID-Prinzipien in jeder Datenbank vollständig ignoriert werden?', 2, '[{"text": "Nein", "correct": true, "because": "ACID ist für Transaktionssicherheit essenziell"}, {"text": "Ja", "correct": false, "because": "Ignorieren führt zu Inkonsistenzen"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches ACID-Prinzip stellt sicher, dass eine Transaktion entweder komplett oder gar nicht ausgeführt wird?', 2, '[{"text": "Atomicity", "correct": true, "because": "Alles-oder-Nichts-Prinzip"}, {"text": "Consistency", "correct": false, "because": "Konsistenter Zustand"}, {"text": "Isolation", "correct": false, "because": "Trennung von Transaktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip garantiert, dass die Datenbank nach einer Transaktion alle Integritätsregeln einhält?', 3, '[{"text": "Consistency", "correct": true, "because": "Sichert konsistenten Zustand"}, {"text": "Atomicity", "correct": false, "because": "Fokus auf Vollständigkeit"}, {"text": "Durability", "correct": false, "because": "Fokus auf Dauerhaftigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches ACID-Prinzip sorgt dafür, dass parallele Transaktionen isoliert voneinander ablaufen?', 2, '[{"text": "Isolation", "correct": true, "because": "Verhindert Interferenzen"}, {"text": "Consistency", "correct": false, "because": "Konsistenter Zustand"}, {"text": "Atomicity", "correct": false, "because": "Alles-oder-Nichts"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip stellt sicher, dass committete Transaktionen dauerhaft gespeichert werden?', 2, '[{"text": "Durability", "correct": true, "because": "Dauerhafte Speicherung"}, {"text": "Isolation", "correct": false, "because": "Trennung von Transaktionen"}, {"text": "Consistency", "correct": false, "because": "Konsistenter Zustand"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches ACID-Prinzip wird durch Rollbacks bei Fehlern unterstützt?', 2, '[{"text": "Atomicity", "correct": true, "because": "Rollbacks sichern Alles-oder-Nichts"}, {"text": "Durability", "correct": false, "because": "Dauerhafte Speicherung"}, {"text": "Isolation", "correct": false, "because": "Trennung von Transaktionen"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien gehören zu den ACID-Prinzipien?', 4, '[{"text": "Atomicity", "correct": true, "because": "Alles-oder-Nichts"}, {"text": "Consistency", "correct": true, "because": "Konsistenter Zustand"}, {"text": "Isolation", "correct": true, "because": "Trennung von Transaktionen"}, {"text": "Flexibility", "correct": false, "because": "Kein ACID-Prinzip"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften beschreiben Atomicity?', 3, '[{"text": "Alles-oder-Nichts", "correct": true, "because": "Vollständige Ausführung"}, {"text": "Rollback bei Fehlern", "correct": true, "because": "Sichert Vollständigkeit"}, {"text": "Transaktion als Einheit", "correct": true, "because": "Unteilbare Operation"}, {"text": "Dauerhafte Speicherung", "correct": false, "because": "Durability"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte gehören zur Consistency?', 4, '[{"text": "Integritätsregeln einhalten", "correct": true, "because": "Konsistenter Zustand"}, {"text": "Fremdschlüsselregeln", "correct": true, "because": "Teil der Konsistenz"}, {"text": "Datenbankregeln", "correct": true, "because": "Regeln gewährleisten"}, {"text": "Trennung von Transaktionen", "correct": false, "because": "Isolation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Mechanismen unterstützen Isolation?', 3, '[{"text": "Sperren", "correct": true, "because": "Verhindert gleichzeitigen Zugriff"}, {"text": "Transaktionslogik", "correct": true, "because": "Sichert Ablauf"}, {"text": "Serialisierbarkeit", "correct": true, "because": "Gewährleistet Reihenfolge"}, {"text": "Dauerhafte Speicherung", "correct": false, "because": "Durability"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen gewährleisten Durability?', 3, '[{"text": "Transaktionslogs", "correct": true, "because": "Speichert Änderungen"}, {"text": "Nichtflüchtiger Speicher", "correct": true, "because": "Dauerhafte Speicherung"}, {"text": "Commit-Bestätigung", "correct": true, "because": "Bestätigt Abschluss"}, {"text": "Parallelverarbeitung", "correct": false, "because": "Isolation"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Atomicity sichert die vollständige Ausführung einer Transaktion. b) Es sorgt für dauerhafte Speicherung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vollständigkeit ja, Speicherung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Consistency hält die Datenbank konsistent. b) Es verhindert parallele Transaktionen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Konsistenz ja, Parallelität nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Isolation trennt parallele Transaktionen. b) Es stellt sicher, dass Daten dauerhaft gespeichert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Trennung ja, Speicherung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Durability garantiert die Dauerhaftigkeit von Transaktionen. b) Es sorgt für die Vollständigkeit der Ausführung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dauerhaftigkeit ja, Vollständigkeit nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Isolation nutzt Sperren zur Trennung. b) Consistency erfordert keine Integritätsregeln.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sperren ja, Regeln nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

